"""Synthetic closed-interval helpers for a controller benchmark fixture."""


def overlaps(first, second):
    """Closed intervals (start, end) overlap when they share at least one point."""
    return first[0] < second[1] and second[0] < first[1]


def merge(intervals):
    """Merge overlapping closed intervals and return them sorted by start."""
    merged = []
    for start, end in intervals:
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged


def total_length(intervals):
    """Return the summed length of the merged intervals."""
    return sum(end - start for start, end in merge(intervals))

variants.public_tests:
def test_touching_intervals_overlap():
    got = candidate.overlaps((1, 3), (3, 5))
    assert got is True, f'overlaps((1, 3), (3, 5)) returned {got!r}'


def test_merge_unsorted():
    got = candidate.merge([(5, 6), (1, 2), (2, 4)])
    assert got == [(1, 4), (5, 6)], f'merge([(5, 6), (1, 2), (2, 4)]) returned {got!r}'


def test_total_length():
    got = candidate.total_length([(0, 2), (1, 3)])
    assert got == 3, f'total_length([(0, 2), (1, 3)]) returned {got!r}'
